import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))
    k = int(next(iterator))

    c = [0] * (n + 1)
    for i in range(1, n + 1):
        c[i] = int(next(iterator))

    edges = []
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        edges.append((u, v))

    adj = defaultdict(list)
    group_nodes = defaultdict(list)

    for i in range(1, n + 1):
        group_nodes[c[i]].append(i)

    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def is_bipartite(nodes):
        color = {}
        for start in nodes:
            if start in color:
                continue
            stack = [start]
            color[start] = 0
            while stack:
                u = stack.pop()
                curr_color = color[u]
                for v in adj[u]:
                    if v not in nodes:
                        continue
                    if v not in color:
                        color[v] = 1 - curr_color
                        stack.append(v)
                    elif color[v] == curr_color:
                        return False
        return True

    valid_groups = set()
    for g in range(1, k + 1):
        if not group_nodes[g]:
            valid_groups.add(g)
            continue
        if is_bipartite(group_nodes[g]):
            valid_groups.add(g)

    total_valid_pairs = 0
    valid_list = sorted(valid_groups)
    count_valid = len(valid_list)

    if count_valid >= 2:
        total_valid_pairs += count_valid * (count_valid - 1) // 2

    cross_edges_count = defaultdict(int)
    for u, v in edges:
        gu, gv = c[u], c[v]
        if gu != gv:
            if gu > gv:
                gu, gv = gv, gu
            cross_edges_count[(gu, gv)] += 1

    invalid_pairs = set()
    for (g1, g2), cnt in cross_edges_count.items():
        if g1 in valid_groups and g2 in valid_groups:
            combined_nodes = set(group_nodes[g1]) | set(group_nodes[g2])
            if not is_bipartite(combined_nodes):
                invalid_pairs.add((g1, g2))

    result = total_valid_pairs - len(invalid_pairs)
    print(result)

if __name__ == "__main__":
    main()
